# Check symmetry
def is_180_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != grid[rows-1-i][cols-1-j]:
                return False
    return True

def is_90_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    if rows != cols:
        return False
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != grid[cols-1-j][i]:
                return False
    return True

def is_vert_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows):
        for j in range(cols//2):
            if grid[i][j] != grid[i][cols-1-j]:
                return False
    return True

def is_horiz_symmetric(grid):
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows//2):
        for j in range(cols):
            if grid[i][j] != grid[rows-1-i][j]:
                return False
    return True

